// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address[] memory _tos, uint[] memory v) public {
        // Keep the arrays non-empty and equal length
        vm.assume(_tos.length > 0);
        vm.assume(v.length == _tos.length);
        // Bound v values to avoid overflow and unrealistic transfers
        for (uint i = 0; i < v.length; i++) {
            v[i] = bound(v[i], 0, type(uint256).max / 1e18);
        }
        // Sender must be the authorized address
        vm.prank(0x9797055B68C5DadDE6b3c7d5D80C9CFE2eecE6c9);
        bool result = c.transfer(_tos, v);
        // The call succeeded (did not revert), so the return value must be true
        assertTrue(result);
    }
}
